// ── 1.2.0, already published ────────────────────────────────────────
class Toast {
  Toast({required this.message, this.seconds = 3});
  final String message;
  final int seconds;
}

abstract class ToastSink {        // no modifier: anyone may implement it
  void show(Toast toast);
}

enum ToastStyle { info, error }

// ── BREAKING: this is 2.0.0, not 1.3.0 ──────────────────────────────
// (the V2 suffixes exist only so both versions fit in one file)
class ToastV2 {
  ToastV2({required this.message, required this.icon});  // new required arg
  final String message;
  final String icon;                                     // every call site breaks
}

abstract class ToastSinkV2 {
  void show(Toast toast);
  void dismiss();                 // every external `implements ToastSink` breaks
}

enum ToastStyleV2 { info, error, warning }
// consumer code that no longer compiles:
//   final label = switch (style) {        // exhaustive in Dart 3 — no default
//     ToastStyle.info  => 'FYI',
//     ToastStyle.error => 'Oops',
//   };

// ── SAFE: this is 1.3.0 ─────────────────────────────────────────────
final class ToastBar {            // final: not implementable, not extendable
  ToastBar({required this.message, this.seconds = 3, this.icon});
  final String message;
  final int seconds;
  final String? icon;             // optional, defaults to null -> additive
  void dismiss() {}               // free to add: nobody outside can implement it
}
